#!/usr/bin/env python3
# =============================================================================
# tests/ffe_orchestrator.py -- far-field (FFE) induction for the threshold-grid
# basis, reproducing mkramer's prc2_r4 sim (branch ffe-test3 @ bee9d14).
#
# WHY THIS EXISTS
#   The mono-threshold basis (tests/threshold_induction_study.py -> ti_mult_grid.npz)
#   is generated by re-simulating mkramer's shower *segments* through a NEAR-FIELD-ONLY
#   induction path at MAX_RADIUS=12 (the full 25x25 fsd_cube response). His reference
#   sim instead ran NEAR-FIELD at MAX_RADIUS=4 PLUS far-field induction (segments mode,
#   infinite_plane dipole, charge_neighbor_radius=4 from ff_r4.yaml). That difference is
#   the entire ~8-bin single-hit-Q gap (our f_T peaks at threshold ~4.5 ke-; his sim +
#   the data peak at ~12 ke-): radius-12 near-field manufactures a huge halo of fringe
#   pixels that cross threshold exactly once, which his radius-4 + separately-classified
#   far-field pixels do not. See memory: mkramer-sim-farfield-config.
#
# WHAT THIS DOES
#   Mirrors the far-field blocks of his cli/simulate_pixels.py @ bee9d14 EXACTLY, so the
#   basis uses HIS far-field code (we vendor his modules; we do not reimplement the physics):
#     - precompute:   pixel_classifier.get_classification_cache(tracks)      (bee9d14 L1299-1307)
#     - category 1:   launch_ffe_kernel(..., category=1) added to NEAR pixels (bee9d14 L1489-1523)
#     - category 0:   launch_ffe_kernel(..., category=0) for far-field-ONLY halo pixels, with the
#                     min(t0) tick offset, appended as NEW pixel rows                (bee9d14 L1545-1620)
#   It operates on the harness pre-signal dict from threshold_induction_study.event_induce
#   (unique_pix, pixels_signals [npix x nt0, t0-inflated frame], + per-pixel aux), extending
#   it in place so the one downstream FEE pass (event_fee_hits) sees near+halo pixels together.
#   Induction is threshold-independent, so this runs ONCE per event and the whole 12x6
#   threshold/reset scan still comes for free.
#
# PREREQUISITE -- VENDOR HIS FAR-FIELD CODE (HEAD's is a stripped-down, different version):
#   On the basis-generation branch, replace HEAD's reduced far-field with his bee9d14 code:
#       git checkout bee9d14 -- larndsim/far_field/ larndsim/consts/ff_induction.py
#   (We do NOT need his sim.py: enable_farfield() sets the sim.FARFIELD_* globals directly,
#   and we do NOT need voxelization.py: segments mode never touches it.) _assert_vendored()
#   below fails loudly with this instruction if HEAD's reduced modules are still in place.
#
# WIRING (one hook in threshold_induction_study.py) -- see integrate_note() at the bottom.
#
# VALIDATION happens on the NERSC GPU (no CUDA here): after one basis regen with
# max_radius=4 + this orchestrator, f_T's single-hit-Q peak should move from ~4.5 to ~12 ke-
# and the map-mixture (predict_known) should track his prc2_r4 sim to ~2%.
# =============================================================================
from math import ceil

import numpy as np

# Required segment/track fields (drifted tracks) for the far-field path, so a missing-field
# failure is reported here rather than deep inside a CUDA kernel.
_FF_TRACK_FIELDS = ("x_start", "y_start", "z_start", "x_end", "y_end", "z_end",
                    "n_electrons", "pixel_plane", "t0")


def _assert_vendored():
    """Fail loudly unless his bee9d14 far-field modules are the ones imported.

    HEAD's far_field is a reduced version (signal_calculation.py ~200 lines shorter, no
    ff_rN radius loading) that does NOT reproduce his r4. The markers checked here exist
    only in his bee9d14 code.
    """
    from larndsim.far_field import signal_calculation
    from larndsim.consts import ff_induction
    missing = []
    if not hasattr(signal_calculation, "launch_ffe_kernel"):
        missing.append("signal_calculation.launch_ffe_kernel")
    if not hasattr(signal_calculation, "calculate_ff_segments"):
        missing.append("signal_calculation.calculate_ff_segments")
    if not hasattr(ff_induction, "set_ff_induction_properties"):
        missing.append("ff_induction.set_ff_induction_properties")
    if not hasattr(ff_induction, "CHARGE_NEIGHBOR_RADIUS"):
        missing.append("ff_induction.CHARGE_NEIGHBOR_RADIUS")
    if missing:
        raise RuntimeError(
            "Far-field code is not mkramer's bee9d14 version (missing: "
            + ", ".join(missing) + ").\nVendor it on this branch with:\n"
            "    git checkout bee9d14 -- larndsim/far_field/ larndsim/consts/ff_induction.py\n"
            "then re-run.")


def enable_farfield(ctx, ff_properties_path, mode="segments",
                    dipole="infinite_plane", max_radius=4):
    """Turn on far-field for the grid harness, matching his prc2_r4 config.

    - loads ff_r4.yaml (charge_neighbor_radius: 4 and the dipole constants) via his loader,
    - sets the sim.FARFIELD_* globals his far_field modules read,
    - pins the NEAR-field reach to `max_radius` (his run overrode MAX_RADIUS 12->4 from an
      uncommitted detector yaml; we set the already-loaded global directly, equivalently).

    Call ONCE after consts.load_properties, before generating the grid. His r4 reference:
        enable_farfield(ctx, ".../farfield_properties/ff_r4.yaml",
                        mode="segments", dipole="infinite_plane", max_radius=4)
    """
    _assert_vendored()
    from larndsim.consts import sim, detector, ff_induction

    ff_induction.set_ff_induction_properties(ff_properties_path)  # charge_neighbor_radius=4, dipole consts
    sim.FARFIELD_ENABLED = True
    sim.FARFIELD_MODE = mode                 # 'segments'
    sim.FARFIELD_DIPOLE_MODE = dipole        # 'infinite_plane'

    # His run set MAX_RADIUS=4 via a detector-yaml override (detector.py:458). We set the
    # loaded global directly so near-field uses radius 4 while the 25x25 response table stays.
    if max_radius is not None:
        detector.MAX_RADIUS = int(max_radius)

    return dict(enabled=True, mode=mode, dipole=dipole,
                max_radius=int(detector.MAX_RADIUS),
                charge_neighbor_radius=int(ff_induction.CHARGE_NEIGHBOR_RADIUS))


def precompute_classification(drifted_tracks):
    """Per-event far-field pre-classification (his bee9d14 simulate_pixels L1299-1307).

    Segments mode only (no voxel_cache). Returns {tpc_idx: PixelClassificationResult}; the
    category-0 step reads .induction_pixels / .induction_pixels_x / .induction_pixels_y off it.
    """
    from larndsim.far_field import pixel_classifier
    _require_fields(drifted_tracks, "precompute_classification")
    return pixel_classifier.get_classification_cache(drifted_tracks)


def apply_farfield(ctx, ev, drifted_tracks, classification_cache):
    """Add far-field (category 1 to near pixels; category 0 halo pixels) to a pre-signal dict.

    `ev` is the dict returned by threshold_induction_study.event_induce. It is extended IN
    PLACE and returned: `pixels_signals` and `unique_pix` grow to include the far-field-only
    halo pixels, and every per-pixel aux array is extended to match (halo pixels are pure
    induction: is_collection=False, q_coll=0, t_coll/sig_t_coll/t_near=nan).

    Faithful to his bee9d14 cli/simulate_pixels.py:
      - category 1 added directly (no offset)                 -> L1489-1523
      - category 0 offset by min(t0) ticks, then appended     -> L1545-1620
    """
    import cupy as cp
    from larndsim.consts import sim
    from larndsim.far_field import signal_calculation

    if not getattr(sim, "FARFIELD_ENABLED", False):
        return ev
    _require_fields(drifted_tracks, "apply_farfield")

    det = ctx.detector
    ts = det.TIME_SAMPLING
    nx, ny = int(det.N_PIXELS[0]), int(det.N_PIXELS[1])
    pitch = det.PIXEL_PITCH

    unique_pix_h = np.asarray(ev["unique_pix"])
    ps_dev = cp.asarray(ev["pixels_signals"], dtype=cp.float32)    # (npix, nt0), t0-inflated
    nt0 = ps_dev.shape[1]

    # Device structured tracks for the FFE kernels (launch_ffe_kernel filters tracks by
    # pixel_plane on-device, then the segment kernel consumes them).
    tracks_dev = cp.asarray(drifted_tracks)
    plane_all = np.asarray(drifted_tracks["pixel_plane"]).astype(np.int32)
    active_tpcs = np.unique(plane_all)

    # --- Pixel (x, y) for the NEAR pixels, exactly as simulate_pixels L1494-1501 ---
    px_idx = unique_pix_h % nx
    py_idx = (unique_pix_h // nx) % ny
    plane_idx = (unique_pix_h // (nx * ny)).astype(int)
    x_min = det.TPC_BORDERS[plane_idx, 0, 0]
    y_min = det.TPC_BORDERS[plane_idx, 1, 0]
    pixel_x = cp.asarray(x_min + (px_idx + 0.5) * pitch, dtype=cp.float32)
    pixel_y = cp.asarray(y_min + (py_idx + 0.5) * pitch, dtype=cp.float32)

    # --- Category 1: far-field contribution to the already-present (near) pixels ---
    for tpc_idx in active_tpcs:
        row_mask = (plane_idx == tpc_idx)                  # host bool over near pixels
        if not row_mask.any():
            continue
        m_dev = cp.asarray(row_mask)
        ff = signal_calculation.launch_ffe_kernel(
            tpc_idx=int(tpc_idx), tracks=tracks_dev,
            pixel_x=pixel_x[m_dev], pixel_y=pixel_y[m_dev],
            n_ticks=nt0, category=1, voxel_cache={})
        ps_dev[m_dev, :] += ff
    ev["pixels_signals"] = cp.asnumpy(ps_dev)

    # --- Category 0: far-field-ONLY halo pixels (not already processed near pixels) ---
    processed = cp.asarray(unique_pix_h)
    t0_arr = np.asarray(drifted_tracks["t0"], dtype=float)
    new_ids, new_sig = [], []
    for tpc_idx in active_tpcs:
        cls = classification_cache.get(int(tpc_idx), None)
        if cls is None or len(cls.induction_pixels) == 0:
            continue
        ind = cp.asarray(cls.induction_pixels, dtype=cp.int32)
        ix = cp.asarray(cls.induction_pixels_x, dtype=cp.float32)
        iy = cp.asarray(cls.induction_pixels_y, dtype=cp.float32)
        keep = ~cp.isin(ind, processed)                    # drop pixels already in near set
        ind, ix, iy = ind[keep], ix[keep], iy[keep]
        if ind.size == 0:
            continue

        ff = signal_calculation.launch_ffe_kernel(
            tpc_idx=int(tpc_idx), tracks=tracks_dev,
            pixel_x=ix, pixel_y=iy, n_ticks=nt0, category=0, voxel_cache={})

        # min(t0) tick offset before digitization (simulate_pixels L1590-1605), incl. his
        # ns->us guard keyed on the TPC drift span.
        min_t0 = float(t0_arr.min())
        z_anode = float(det.TPC_BORDERS[int(tpc_idx), 2, 0])
        z_cathode = float(det.TPC_BORDERS[int(tpc_idx), 2, 1])
        z_span_us = abs(z_cathode - z_anode) / det.V_DRIFT
        min_t0_us = (min_t0 / 1000.0
                     if (z_span_us > 0 and min_t0 / max(z_span_us, 1e-9) > 500) else min_t0)
        offset = int(np.clip(ceil(min_t0_us / ts), 0, nt0))
        shifted = cp.zeros_like(ff)
        if offset > 0:
            usable = nt0 - offset
            if usable > 0:
                shifted[:, offset:offset + usable] = ff[:, :usable]
        else:
            shifted = ff
        new_ids.append(cp.asnumpy(ind))
        new_sig.append(cp.asnumpy(shifted))

    if new_ids:
        halo_ids = np.concatenate(new_ids)
        halo_sig = np.concatenate(new_sig, axis=0).astype(ev["pixels_signals"].dtype)
        _append_halo_pixels(ev, halo_ids, halo_sig, ts)

    return ev


def _append_halo_pixels(ev, halo_ids, halo_sig, ts):
    """Append far-field-only pixel rows to the pre-signal dict, extending every per-pixel
    array so the single downstream FEE pass sees a consistent (near + halo) pixel set.

    Halo pixels are pure induction: no collected charge or arrival-time truth.
    """
    n_halo = int(halo_ids.size)
    ev["unique_pix"] = np.concatenate([np.asarray(ev["unique_pix"]), halo_ids.astype(ev["unique_pix"].dtype)])
    ev["pixels_signals"] = np.concatenate([ev["pixels_signals"], halo_sig], axis=0)

    def _ext(key, fill, dtype):
        if key in ev and ev[key] is not None and np.asarray(ev[key]).ndim == 1:
            ev[key] = np.concatenate([np.asarray(ev[key]),
                                      np.full(n_halo, fill, dtype=dtype)])

    _ext("is_collection", False, bool)          # halo = induction, never collection
    _ext("q_coll", 0.0, float)                  # no charge landed on the pad
    _ext("t_coll", np.nan, float)
    _ext("sig_t_coll", np.nan, float)
    _ext("t_near", np.nan, float)
    # net collected charge truth = per-row signal integral (matches event_induce's truth_e)
    _ext("truth_e", 0.0, float)
    if "truth_e" in ev and ev["truth_e"] is not None:
        ev["truth_e"][-n_halo:] = halo_sig.sum(axis=1, dtype=np.float64) * ts
    # backtrack arrays are per-pixel and already zeroed in event_induce; keep them per-pixel.
    for key in ("num_backtrack", "offset_backtrack"):
        if key in ev and np.asarray(ev[key]).ndim == 1 and np.asarray(ev[key]).size:
            ev[key] = np.concatenate([np.asarray(ev[key]),
                                      np.zeros(n_halo, dtype=np.asarray(ev[key]).dtype)])


def _require_fields(tracks, where):
    names = getattr(getattr(tracks, "dtype", None), "names", None) or ()
    missing = [f for f in _FF_TRACK_FIELDS if f not in names]
    if missing:
        raise ValueError(f"{where}: drifted tracks missing far-field fields {missing}; "
                         f"present: {tuple(names)}")


def integrate_note():
    """How to wire this into the grid harness (threshold_induction_study.py).

    1) Once, right after consts.load_properties (near the SimContext setup), for an r4 basis:

           from tests import ffe_orchestrator as ffe
           if args.farfield:                       # new CLI flag, default off (keeps the
                                                   # near-field-only basis reproducible)
               ffe.enable_farfield(ctx, args.farfield_properties,   # .../ff_r4.yaml
                                   mode="segments", dipole="infinite_plane", max_radius=4)

    2) In event_induce(), after the pre-signal dict is built (the `return dict(...)`),
       add the far-field contribution once per event (induction is threshold-independent,
       so the whole threshold/reset scan reuses it):

           ev = dict(unique_pix=uph, pixels_signals=ps_host, ...)   # existing
           if getattr(sim, "FARFIELD_ENABLED", False):
               cache = ffe.precompute_classification(drifted)       # drifted = the event's tracks
               ev = ffe.apply_farfield(ctx, ev, drifted, cache)
           return ev

       (event_induce already receives `drifted`; pass it straight through. In the
       cached-scan path, far-field is applied when the pre-signal is first built, so it is
       cached alongside pixels_signals and costs nothing on rescan.)

    3) Regenerate the basis on NERSC with --farfield --farfield-properties .../ff_r4.yaml,
       same 598 segments, max_radius=4. Expect f_T single-hit-Q peak ~4.5 -> ~12 ke-.
    """
    return integrate_note.__doc__
